# Combining the two
dat_long &lt;- dat_spring |&gt;
  bind_rows(dat_fall) |&gt;
  # merge comments and note columns
  unite("Remarks",
    contains(c("Comment", "Notes")),
    sep = ". ",
    na.rm = TRUE
  ) |&gt;
  # merge observer columns
  unite("Observer",
    contains("Observer"),
    sep = ". ",
    na.rm = TRUE
  ) |&gt;
  mutate(year = year(date))

rm(dat_fall, dat_spring)
